        <script>
          const TOTAL_ROWS = 10000;
          const ROW_HEIGHT = 40;
          const VISIBLE_ROWS = Math.ceil(600 / ROW_HEIGHT) + 2;

          const scroller = document.getElementById('scroller');
          const content = document.getElementById('content');
          const visibleRowsSpan = document.getElementById('visible-rows');
          const scrollPositionSpan = document.getElementById('scroll-position');

          // Set total height
          content.style.height = (TOTAL_ROWS * ROW_HEIGHT) + 'px';

          let currentStartIndex = 0;
          let renderedRows = new Map();

          function createRow(index) {
            const row = document.createElement('div');
            row.className = 'row';
            row.style.position = 'absolute';
            row.style.top = (index * ROW_HEIGHT) + 'px';
            row.style.width = '100%';
            row.style.left = '0';
            row.setAttribute('data-index', index);

            const timestamp = new Date(Date.now() - Math.random() * 1000000000).toISOString();
            row.innerHTML = `
              <div class="row-id">ID: ${index + 1}</div>
              <div class="row-data">Row ${index + 1} - Sample Data</div>
              <div class="row-timestamp">${timestamp}</div>
            `;

            return row;
          }

          function updateVirtualScroll() {
            const scrollTop = scroller.scrollTop;
            const startIndex = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - 1);
            const endIndex = Math.min(TOTAL_ROWS, startIndex + VISIBLE_ROWS + 1);

            scrollPositionSpan.textContent = Math.round(scrollTop);
            visibleRowsSpan.textContent = endIndex - startIndex;

            // Remove rows that are out of view
            for (const [index, row] of renderedRows) {
              if (index < startIndex || index >= endIndex) {
                row.remove();
                renderedRows.delete(index);
              }
            }

            // Add rows that are in view
            for (let i = startIndex; i < endIndex; i++) {
              if (!renderedRows.has(i)) {
                const row = createRow(i);
                content.appendChild(row);
                renderedRows.set(i, row);
              }
            }

            currentStartIndex = startIndex;
          }

          scroller.addEventListener('scroll', updateVirtualScroll, { passive: true });

          // Initial render
          updateVirtualScroll();

          // Expose for testing
          window.getScrollStats = () => ({
            scrollTop: scroller.scrollTop,
            renderedCount: renderedRows.size,
            startIndex: currentStartIndex
          });

          window.scrollToRow = (rowIndex) => {
            scroller.scrollTop = rowIndex * ROW_HEIGHT;
          };
        </script>
      </body>
      </html>
    `);
